// Anfrage der App (Text-Body mit JSON)
let req = {};
try { req = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : (msg.payload || {}); } catch (e) {}

const rnd = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;
const pick = list => list[Math.floor(Math.random() * list.length)];

let machineStart = flow.get('machineStart');
if (!machineStart) {
    machineStart = new Date(Date.now() - rnd(20 * 60, 8 * 3600) * 1000).toISOString();
    flow.set('machineStart', machineStart);
}
const scanCount = (flow.get('scanCount') || 0) + 1;
flow.set('scanCount', scanCount);

let kugeln = ['Blau', 'Rot', 'Grün']
    .map(farbe => ({ farbe, anzahl: rnd(0, 5) }))
    .filter(k => k.anzahl > 0);
if (kugeln.length === 0) kugeln = [{ farbe: pick(['Blau', 'Rot', 'Grün']), anzahl: rnd(1, 5) }];

const auftrag = {
    orderNumber: 'AUF-' + String(rnd(1, 99999)).padStart(5, '0'),
    palletNumber: String(rnd(1, 9999)).padStart(4, '0'),
    palletCount: rnd(4, 20),
    order: { dose: 'Weiß', deckel: pick(['Blau', 'Rot', 'Grün']), kugeln },
    vibration: flow.get('vibration') ?? null,
    machineStart,
    scanCount,
    marker: req.marker || null,
    timestamp: new Date().toISOString()
};
flow.set('lastOrder', auftrag);

msg.statusCode = 201;   // Created
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store'
};
msg.payload = auftrag;
node.status({ fill: 'green', shape: 'dot', text: '201 · ' + auftrag.orderNumber + ' · Scan ' + scanCount });
return msg;

const last = flow.get('lastOrder');
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store'
};
if (!last) {
    msg.statusCode = 404;   // Not Found
    msg.payload = { error: 'Noch kein Auftrag vorhanden' };
} else {
    msg.statusCode = 200;   // OK
    msg.payload = last;
}
return msg;

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store'
};
msg.statusCode = 200;
msg.payload = {
    value: flow.get('vibration') ?? null,
    nodeId: 'ns=2;s=Demo.Alarms.Plant.PowerHouse.P-101.Vibration',
    timestamp: new Date().toISOString()
};
return msg;

// Bestätigung des Abos ignorieren
if (msg.topic === 'subscriptionId') return null;

// Wert kann je nach Version direkt oder als DataValue kommen
let v = msg.payload;
if (v && typeof v === 'object') {
    v = (v.value && typeof v.value === 'object') ? v.value.value : v.value;
}
v = Number(v);
if (!Number.isFinite(v)) return null;

flow.set('vibration', v);
node.status({ fill: 'yellow', shape: 'dot', text: v.toFixed(3) });

msg.topic = 'lf7/zwischenlager-emirhantlc/vibration';
msg.payload = {
    value: v,
    unit: '',
    nodeId: 'ns=2;s=Demo.Alarms.Plant.PowerHouse.P-101.Vibration',
    timestamp: new Date().toISOString()
};
return msg;

